<?php
namespace App\Controllers;use App\Models\Photo;use App\Models\PhotoSet;use App\Core\Database;
final class StoreController{
 public function index():void{$db=Database::db();$photos=Photo::all(trim($_GET['q']??''));$cta=$db->query("SELECT * FROM homepage_cta WHERE id=1 AND active=1")->fetch()?:null;$events=$db->query("SELECT e.*,COUNT(DISTINCT p.id) photos_count,COUNT(DISTINCT ps.id) sets_count,MIN(p.id) cover_id,MIN(p.preview_path) cover,MIN(ps.set_price) from_set_price FROM events e LEFT JOIN photos p ON p.event_id=e.id AND p.status='active' LEFT JOIN photo_sets ps ON ps.event_id=e.id AND ps.status='active' AND ps.set_enabled=1 GROUP BY e.id ORDER BY e.event_date DESC LIMIT 3")->fetchAll();$sets=$db->query("SELECT ps.*,e.name event_name,COUNT(p.id) photos_count,MIN(p.id) cover_id,MIN(p.preview_path) preview_path FROM photo_sets ps JOIN events e ON e.id=ps.event_id JOIN photos p ON p.set_id=ps.id AND p.status='active' WHERE ps.status='active' AND ps.set_enabled=1 GROUP BY ps.id ORDER BY ps.id DESC LIMIT 6")->fetchAll();$setPreviews=[];$rows=$db->query("SELECT id,set_id,preview_path FROM photos WHERE set_id IS NOT NULL AND status='active' ORDER BY id")->fetchAll();foreach($rows as $row)if(count($setPreviews[$row['set_id']]??[])<4)$setPreviews[$row['set_id']][]=$row;view('store/index',['photos'=>$photos,'events'=>$events,'sets'=>$sets,'setPreviews'=>$setPreviews,'cta'=>$cta]);}
 public function photo():void{$photo=Photo::find((int)($_GET['id']??0));if(!$photo){http_response_code(404);exit('Foto no encontrada');}$related=$photo['set_id']?PhotoSet::photos((int)$photo['set_id']):[$photo];view('store/photo',['photo'=>$photo,'related'=>$related,'pageTitle'=>'Detalle de fotografía | Ultra','flowPage'=>true,'bodyClass'=>'inner','toplineRight'=>'SELECCIONA TUS FOTOS']);}
 public function faq():void{view('store/faq',['pageTitle'=>'Preguntas frecuentes | Ultra','flowPage'=>true,'bodyClass'=>'inner','faqPage'=>true]);}
}
